};

export const getAgents: GetAgents<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }
  const agents = await context.entities.User.findMany({
    where: { role: 'AGENT' },
    include: {
      ticketsAssigned: {
        where: { NOT: { status: 'RESOLVED' } }
      }
    }
  });
  return agents.map(agent => ({
